public static int[][] rotateMatrix(int[][] matrix) {
    int n = matrix.length;
    int[][] result = new int[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            result[i][j] = matrix[n - j - 1][i];
        }
    }
    return result;
}
