public int findMinFibonacciNumbers(int k) {
    int fib1 = 1;
    int fib2 = 1;
    int fib3 = fib1 + fib2;
    int count = 0;
    while (fib3 <= k) {
        if (fib3 == k) {
            count++;
            break;
        } else if (fib3 < k) {
            fib1 = fib2;
            fib2 = fib3;
            fib3 = fib1 + fib2;
            count++;
        } else {
            break;
        }
    }
    return count;
}
